"""Regression checks for capture fixtures and the independent Matrix receiver."""
import base64
from collections.abc import Callable
import copy
import json
import os
from pathlib import Path
import re
import sys
import time
from typing import Any
import unittest
import uuid

from cryptography.exceptions import InvalidSignature
import matrix_receipt as receiver

REQUESTS: list[dict[str, Any]] = json.loads(sys.argv.pop(1))


class ContractFixtures(unittest.TestCase):
    def test_upstream_crypto_vectors(self) -> None:
        # Existing vectors were generated by upstream, not by this receiver.
        vectors = (Path(__file__).resolve().parents[2] / "matrixolm/vectors_test.go").read_text()
        def vector(name: str) -> str:
            return re.search(name+r' = "([^"]+)"', vectors).group(1)
        identity = receiver.public(bytes(i+1 for i in range(32)))
        self.assertEqual(receiver.decrypt_olm(vector("upstreamOlmPreKeyMessage"), identity), {"algorithm":"m.megolm.v1.aes-sha2"})
        key = vector("upstreamMegolmSessionKey")
        session_id = base64.b64encode(receiver.b64(key)[133:165]).decode().rstrip("=")
        self.assertEqual(receiver.decrypt_megolm(vector("upstreamMegolmCiphertext"), key, session_id), {"body":"cross check", "msgtype":"m.text"})

    def test_capture_uuid_and_clock_remain_live(self) -> None:
        import capture_request
        from apprise.plugins.matrix.e2ee import MatrixOlmAccount
        original_uuid, original_clock = uuid.uuid4, time.time
        os.environ["APPRISE_FIXED_TIME"] = "2024-01-01T00:00:00Z"
        capture_request.apply_fixed_time()
        self.assertIs(uuid.uuid4, original_uuid)
        self.assertIs(time.time, original_clock)
        self.assertNotEqual(uuid.uuid4(), uuid.uuid4())
        account = MatrixOlmAccount()
        keys = account.one_time_keys_payload("@fixture:example.com", "FIXTURE", count=50)
        self.assertEqual(len(keys), 50)
        self.assertEqual(len({v["key"] for v in keys.values()}), 50)

    def test_schema_enum_defaults_use_wire_values(self) -> None:
        from apprise.common import NotifyFormat
        from schema_exercise_cases import query_value_from_default
        self.assertEqual(query_value_from_default(NotifyFormat.HTML, {}), "html")

    def test_valid_delivery_recovers_message(self) -> None:
        requests = receiver.normalize_requests(REQUESTS)
        event = json.loads(requests[-1]["body"])["event"]
        self.assertEqual(event["content"]["body"], "# secret title\r\nsecret body")

    def test_tampered_delivery_is_rejected(self) -> None:
        def mutate(
            endpoint: str, change: Callable[[dict[str, Any]], None]
        ) -> list[dict[str, Any]]:
            requests = copy.deepcopy(REQUESTS)
            request = next(r for r in requests if endpoint in r["url"])
            payload = json.loads(request["body"])
            change(payload)
            request["body"] = json.dumps(payload)
            return requests

        def device_signature(payload: dict[str, Any]) -> None:
            key = payload["device_keys"]
            key["signatures"][key["user_id"]]["ed25519:"+key["device_id"]] = base64.b64encode(bytes(64)).decode()

        def room_cipher(payload: dict[str, Any]) -> None:
            message = next(iter(next(iter(payload["messages"].values())).values()))
            cipher = next(iter(message["ciphertext"].values()))
            data = bytearray(receiver.b64(cipher["body"]))
            data[-1] ^= 1
            cipher["body"] = base64.b64encode(data).decode()

        def event_cipher(payload: dict[str, Any]) -> None:
            data = bytearray(receiver.b64(payload["ciphertext"]))
            data[-1] ^= 1
            payload["ciphertext"] = base64.b64encode(data).decode()

        def wrong_recipient(payload: dict[str, Any]) -> None:
            payload["messages"]["@intruder:example.com"] = payload["messages"].pop(receiver.RECEIVER_USER)

        cases = {
            "device signature": mutate("/keys/upload", device_signature),
            "Olm MAC": mutate("/sendToDevice/", room_cipher),
            "Megolm signature": mutate("/send/m.room.encrypted/", event_cipher),
            "room-key recipient": mutate("/sendToDevice/", wrong_recipient),
            "missing room key": [r for r in REQUESTS if "/sendToDevice/" not in r["url"]],
        }
        for name, requests in cases.items():
            with self.subTest(name=name), self.assertRaises((ValueError, KeyError, InvalidSignature)):
                receiver.normalize_requests(requests)


if __name__ == "__main__":
    unittest.main()
